from marshmallow import __version__, __version_info__


class TestVersionInfo:
    def test_version_info_is_tuple_of_ints(self):
        assert isinstance(__version_info__, tuple)
        for part in __version_info__:
            assert isinstance(part, int)

    def test_version_info_matches_version(self):
        parts = [int(x) for x in __version__.split(".")]
